import { execFileSync } from 'node:child_process';
const ref = 'sf-next/next';
const show = (path) => execFileSync('git', ['show', `${ref}:${path}`], {encoding:'utf8'});
const list = JSON.parse(show('release-packages.json')).map(entry => {
  const pkg = JSON.parse(show(`${entry.path}/package.json`));
  return {...entry, branchVersion: pkg.version};
});
function parts(v) {
  const m = String(v).match(/^(\d+)\.(\d+)\.(\d+)(?:-([^+]+))?(?:\+.*)?$/);
  return m ? {nums:[+m[1],+m[2],+m[3]], pre:m[4] ?? null} : null;
}
function cmp(a,b) {
  const pa=parts(a), pb=parts(b); if (!pa || !pb) return String(a).localeCompare(String(b), undefined, {numeric:true});
  for(let i=0;i<3;i++) if(pa.nums[i]!==pb.nums[i]) return pa.nums[i]-pb.nums[i];
  if(pa.pre===null && pb.pre!==null) return 1; if(pa.pre!==null && pb.pre===null) return -1;
  return String(pa.pre??'').localeCompare(String(pb.pre??''), undefined, {numeric:true});
}
const results = new Array(list.length);
let cursor=0;
async function worker(){
  while(true){
    const i=cursor++; if(i>=list.length) return;
    const item=list[i];
    const url=`https://registry.npmjs.org/${encodeURIComponent(item.name)}`;
    try {
      const res=await fetch(url,{headers:{accept:'application/vnd.npm.install-v1+json'}});
      if(res.status===404){results[i]={...item,status:'unpublished'};continue;}
      if(!res.ok){results[i]={...item,status:'error',error:`HTTP ${res.status}`};continue;}
      const data=await res.json();
      const versions=Object.keys(data.versions??{});
      const latest=data['dist-tags']?.latest??null;
      const highestStable=versions.filter(v=>parts(v)?.pre===null).sort(cmp).at(-1)??null;
      const collision=versions.includes(item.branchVersion);
      const relation=latest ? Math.sign(cmp(item.branchVersion,latest)) : null;
      results[i]={...item,status:'published',latest,highestStable,collision,relation};
    } catch(error){results[i]={...item,status:'error',error:String(error.message??error)};}
  }
}
