  behind:published.filter(r=>r.relation<0).map(r=>`${r.name}: branch ${r.branchVersion}, npm latest ${r.latest}`),
  ahead:published.filter(r=>r.relation>0).map(r=>`${r.name}: branch ${r.branchVersion}, npm latest ${r.latest}`),
  exactCollisions:published.filter(r=>r.collision).map(r=>`${r.name}@${r.branchVersion}`),
};
